INSERT INTO "email_recipients" ("id", "email_id", "recipient_type", "name", "email", "client_id", "contact_id") VALUES ('c34b4be2-c789-4c9b-8ae9-41cb5f7d5813', 'c7af583f-b1c3-4da8-bca4-3db855e279d0', 'to', 'Bhatti – CEO', 'ushafiq0011@gmail.com', 'd73a26bd-26d4-42d3-904b-fab24997fc9a', 'e9e11416-4ff7-4501-8abb-44b51d1bf5ad');
INSERT INTO "email_templates" ("id", "sub_company_id", "name", "subject", "body_html", "header_html", "footer_html", "created_at", "updated_at") VALUES ('1d4ee661-01f2-4495-bf65-87937fc9d35e', NULL, 'Professional Introduction', 'Introduction – {{company_name}} & NA Staffing', '<p>Dear {{contact_name}},</p><p>I hope this message finds you well. I wanted to introduce myself and our team at NA Staffing.</p><p>We specialize in connecting talented professionals with leading organizations, and we would value the opportunity to discuss how we can support {{company_name}}.</p><p>Would you have 15 minutes this week for a brief call to explore whether there might be a fit?</p><p>Best regards,</p>', '<div style="font-family: Georgia, serif; color: #1e3a5f; border-bottom: 2px solid #1e3a5f; padding-bottom: 12px; margin-bottom: 24px;"><strong>NA Staffing</strong></div>', '<div style="margin-top: 32px; padding-top: 16px; border-top: 1px solid #e5e7eb; font-size: 12px; color: #6b7280;">NA Staffing · Talent & Staffing Solutions</div>', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)');
INSERT INTO "email_templates" ("id", "sub_company_id", "name", "subject", "body_html", "header_html", "footer_html", "created_at", "updated_at") VALUES ('cd115627-cdf2-4f3c-ba72-32d128cb921e', NULL, 'Follow-up', 'Following up – {{company_name}}', '<p>Hi {{contact_name}},</p><p>I wanted to follow up on our recent conversation. Do you have any questions about our services or the proposal we shared?</p><p>I am happy to schedule a call at your convenience or provide any additional information you need.</p><p>Thank you,</p>', '<div style="font-family: Georgia, serif; color: #1e3a5f; border-bottom: 2px solid #1e3a5f; padding-bottom: 12px; margin-bottom: 24px;"><strong>NA Staffing</strong></div>', '<div style="margin-top: 32px; padding-top: 16px; border-top: 1px solid #e5e7eb; font-size: 12px; color: #6b7280;">NA Staffing · Talent & Staffing Solutions</div>', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)');
INSERT INTO "email_templates" ("id", "sub_company_id", "name", "subject", "body_html", "header_html", "footer_html", "created_at", "updated_at") VALUES ('981b7349-a08e-44ab-b516-94f1c0ef12f1', NULL, 'Thank You', 'Thank you – {{company_name}}', '<p>Dear {{contact_name}},</p><p>Thank you for your time and the opportunity to present our staffing solutions to {{company_name}}.</p><p>We look forward to the next steps and to building a lasting partnership.</p><p>Best regards,</p>', '<div style="font-family: Georgia, serif; color: #1e3a5f; border-bottom: 2px solid #1e3a5f; padding-bottom: 12px; margin-bottom: 24px;"><strong>NA Staffing</strong></div>', '<div style="margin-top: 32px; padding-top: 16px; border-top: 1px solid #e5e7eb; font-size: 12px; color: #6b7280;">NA Staffing · Talent & Staffing Solutions</div>', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)');
INSERT INTO "email_templates" ("id", "sub_company_id", "name", "subject", "body_html", "header_html", "footer_html", "created_at", "updated_at") VALUES ('d1d872c4-e144-4ca2-a6dd-c1248ed8d2d6', NULL, 'Meeting Request', 'Meeting request – {{company_name}}', '<p>Hi {{contact_name}},</p><p>I would like to schedule a short meeting to discuss how NA Staffing can support {{company_name}}.</p><p>Please let me know your availability for a 20–30 minute call in the coming days, or feel free to book a time that works for you using the link below.</p><p>Best regards,</p>', '<div style="font-family: Georgia, serif; color: #1e3a5f; border-bottom: 2px solid #1e3a5f; padding-bottom: 12px; margin-bottom: 24px;"><strong>NA Staffing</strong></div>', '<div style="margin-top: 32px; padding-top: 16px; border-top: 1px solid #e5e7eb; font-size: 12px; color: #6b7280;">NA Staffing · Talent & Staffing Solutions</div>', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)');
INSERT INTO "email_templates" ("id", "sub_company_id", "name", "subject", "body_html", "header_html", "footer_html", "created_at", "updated_at") VALUES ('6b7d35f2-83a9-40d7-b3f5-dc3773079e4c', NULL, 'Proposal Follow-up', 'Proposal for {{company_name}} – next steps', '<p>Dear {{contact_name}},</p><p>I am following up on the proposal we sent for {{company_name}}. Have you had a chance to review it with your team?</p><p>I would be glad to walk you through the details or answer any questions. Please let me know when would be a good time to connect.</p><p>Thank you,</p>', '<div style="font-family: Georgia, serif; color: #1e3a5f; border-bottom: 2px solid #1e3a5f; padding-bottom: 12px; margin-bottom: 24px;"><strong>NA Staffing</strong></div>', '<div style="margin-top: 32px; padding-top: 16px; border-top: 1px solid #e5e7eb; font-size: 12px; color: #6b7280;">NA Staffing · Talent & Staffing Solutions</div>', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)', 'Mon Mar 02 2026 17:22:57 GMT-0500 (Eastern Standard Time)');
